    /**
     * Tests getting all CreativeAssets.
     *
     * @return    Collection
     */
    public List<CreativeAsset> testGetAll() throws Throwable {
    LOGGER.info( "CreativeAssetTest:testGetAll() - Retrieving Collection of CreativeAssets:" );

    StringBuilder msg = new StringBuilder( "-- Failed to get all CreativeAsset : " );
    List<CreativeAsset> collection  = null;

    try {
        // call the static get method on the CreativeAssetService
        collection = service.getAllCreativeAsset();

        if ( collection == null || collection.size() == 0 ) {
            LOGGER.warning( unexpectedErrorMsg );
            LOGGER.warning( "-- " + msg.toString() + " Empty collection returned."  );
        }
        else {
            // Now print out the values
            CreativeAsset currEntity  = null;
            Iterator<CreativeAsset> iter = collection.iterator();

            while( iter.hasNext() ) {
                // Retrieve the entity
                currEntity = iter.next();

                assertNotNull( currEntity,"-- null value object in Collection." );
                assertNotNull( currEntity.getCreativeAssetId(), "-- value object in Collection has a null primary key" );

                LOGGER.info( " - " + currEntity.toString() );
            }
        }
    }
    catch ( Throwable e ){
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() );

        throw e;
    }

    return( collection );
}

